export type GatewayRouteProbeProbeMode =
  (typeof GatewayRouteProbeProbeMode)[keyof typeof GatewayRouteProbeProbeMode];

export const GatewayRouteProbeProbeMode = {
  auto: "auto",
  manual: "manual",
} as const;

export type GatewayRouteProbeStatus =
  (typeof GatewayRouteProbeStatus)[keyof typeof GatewayRouteProbeStatus];

export const GatewayRouteProbeStatus = {
  unverified: "unverified",
  ok: "ok",
  unsupported: "unsupported",
  failed: "failed",
} as const;

export type GatewayRouteProbeSource =
  (typeof GatewayRouteProbeSource)[keyof typeof GatewayRouteProbeSource];

export const GatewayRouteProbeSource = {
  probe: "probe",
  operator: "operator",
} as const;

/**
 * What is known about one endpoint of one route. This is the route's only
 * capability record — nothing is declared — and two readers use it with
 * two different thresholds:
 *
 * - the data plane tries the route for an endpoint unless the status is
 *   `unsupported`;
 * - the catalogue publishes an endpoint only when the status is `ok`.
 *
 * `unverified` — not probed yet, or not probed automatically, as with
 * images. `ok` — a call got through. `unsupported` — the upstream answered
 * 404 or 405: a definitive "nothing here for this model". `failed` — an
 * inconclusive answer (400/422 to the probe's minimal body, 5xx, timeout,
 * credential or quota): shown with the upstream's words, never used to take
 * the route out of rotation, and never downgrading an earlier `ok`.
 *
 * `source` says who wrote it: `probe` for the worker, `operator` for an
 * override, which the worker then leaves alone. `probe_mode` says whether
 * the worker probes the endpoint on its own (`auto`) or only when asked
 * (`manual`, images — it costs a real generation); a manual endpoint is
 * also not a candidate until a verdict says `ok`.
 *
 * Every field of the latest probe is recorded even when the verdict
 * stands: an `ok` row whose `status_code` is 4xx/5xx says "verified, but
 * the last look failed" — the page shows that, the verdict does not move
 * on one inconclusive sample.
 */
export interface GatewayRouteProbe {
  endpoint: GatewayRouteProbeEndpoint;
  probe_mode: GatewayRouteProbeProbeMode;
  status: GatewayRouteProbeStatus;
  source: GatewayRouteProbeSource;
  /** @nullable */
  checked_at?: string | null;
  /** @nullable */
  latency_ms?: number | null;
  /**
   * Upstream HTTP status; empty when the connection itself failed
   * @nullable
   */
  status_code?: number | null;
  /** The upstream text, truncated and otherwise unaltered. It is the only clue separating a bad credential from a bad model name or an unsupported endpoint. */
  error?: string;
  /**
   * When a probe was queued, and null once its verdict has landed. It is a field of its own and not a fifth `status`, because `status` is the verdict and a re-probe must not erase the standing one: the catalogue publishes endpoints found `ok`, so a pending value living in `status` would take the route out of the catalogue for as long as the re-probe ran (ADR-0224).
   *
   * It is what lets the interface say "this is running" — which matters most on the endpoints that are never probed automatically, because each of those costs a real generation and the alternative to saying so is an operator paying for it twice.
   * @nullable
   */
  probe_enqueued_at?: string | null;
}

/**
 * `always` is a model whose sound is native and has no parameter; `optional` is one with a switch; `never` is silent.
 */
export type VideoEnvelopeAudio = (typeof VideoEnvelopeAudio)[keyof typeof VideoEnvelopeAudio];

export const VideoEnvelopeAudio = {
  never: "never",
  optional: "optional",
  always: "always",
} as const;

/**
 * How far a job of this model can be stopped. Declared because the vendors genuinely differ, and unset reads as `never`: an operator who has not said a model can be stopped has not promised that it can.
 */
export type VideoEnvelopeCancel = (typeof VideoEnvelopeCancel)[keyof typeof VideoEnvelopeCancel];

export const VideoEnvelopeCancel = {
  never: "never",
  queued_only: "queued_only",
  anytime: "anytime",
} as const;

/**
 * Where this came from. `observed` means a vendor's own capability endpoint answered it; `declared` means a person typed it.
 *
 * Read-only on purpose. The rule is that the interface must never show a person's entry as an observation, and an input able to set this field is exactly how that rule gets broken. The write path always stores `declared`, and `observed` is reserved for a capability-discovery path. No vendor in this build publishes one, so today every envelope is `declared` — which the interface says rather than leaving the reader to assume.
 */
export type VideoEnvelopeSource = (typeof VideoEnvelopeSource)[keyof typeof VideoEnvelopeSource];

export const VideoEnvelopeSource = {
  observed: "observed",
  declared: "declared",
} as const;

/**
 * What one deployment of a video model accepts. It lives on the route rather than the model because the same model on two channels can accept different duration steps, and it is load-bearing: admission validates against the union of the candidate routes' envelopes and refuses outside it *before* any hold is taken (ADR-0221).
 *
 * Declared, not observed -- the one deliberate exception to "capability is observed". Answering "does this model accept a twelve-second clip" costs a twelve-second clip, and the value space is duration x resolution x aspect ratio x audio. What makes the exception safe is that neither direction of drift bills anyone wrongly: declaring too little refuses at admission having spent nothing, declaring too much ends in an upstream refusal, a failed job and a voided hold.
 *
 * Typed and closed rather than the free-form object the transport profile beside it is. That one is the server's to judge; this one decides whether money moves, and the schema is the only place its shape is stated.
 */
export interface VideoEnvelope {
  /**
   * The clip lengths this deployment accepts. Nothing here is "roughly" anything — 4/6/8, 5/10 and 4/8/12 are three real vendors, and a request outside the set is refused rather than rounded.
   * @items.minimum 1
   */
  durations_seconds?: number[];
  /** @items.maxLength 40 */
  resolutions?: string[];
  /** @items.maxLength 20 */
  aspect_ratios?: string[];
  /** `always` is a model whose sound is native and has no parameter; `optional` is one with a switch; `never` is silent. */
  audio?: VideoEnvelopeAudio;
  /** @minimum 0 */
  max_n?: number;
  supports_image_to_video?: boolean;
  /** Separate from `supports_image_to_video` because upstreams gate the two separately — one accepts an end frame only in its pro mode. */
  supports_last_frame?: boolean;
  /**
   * 0 where steering images are not accepted at all
   * @minimum 0
   */
  max_reference_images?: number;
  /** Declared rather than assumed. It is near-universal but not universal, and silently dropping it bills the caller for a clip that ignored half of what they asked for. */
  supports_negative_prompt?: boolean;
  /**
   * In characters, and upstream limits are not always: one vendor publishes 2000 characters, another publishes 1024 *tokens*. Configuring a token limit here as if it were characters refuses valid prompts, so a model whose limit is not expressed in characters leaves this at 0 and lets the upstream be the one to refuse.
   * @minimum 0
   */
  max_prompt_chars?: number;
  /** How far a job of this model can be stopped. Declared because the vendors genuinely differ, and unset reads as `never`: an operator who has not said a model can be stopped has not promised that it can. */
  cancel?: VideoEnvelopeCancel;
  /**
   * This model's own ceiling on how long a job may run before the reconciler calls it expired. It also sizes the hold's TTL, which is why it belongs to the model rather than to one global constant.
   * @minimum 0
   */
  max_job_seconds?: number;
  /**
   * Where this came from. `observed` means a vendor's own capability endpoint answered it; `declared` means a person typed it.
   *
   * Read-only on purpose. The rule is that the interface must never show a person's entry as an observation, and an input able to set this field is exactly how that rule gets broken. The write path always stores `declared`, and `observed` is reserved for a capability-discovery path. No vendor in this build publishes one, so today every envelope is `declared` — which the interface says rather than leaving the reader to assume.
   */
  readonly source?: VideoEnvelopeSource;
}

export interface GatewayRoute {
  id: string;
  model_id: string;
  model_slug: string;
  provider_id: string;
  provider_slug: string;
  /**
   * The protocols the route's provider speaks, carried with the row
   * because they say which endpoints this route can be asked about:
   * `probes` has one entry per endpoint of each of these.
   */
  provider_protocols: string[];
  /** The real upstream model name; the request body's model field is rewritten to this */
  provider_model_id: string;
  priority: number;
  weight: number;
  enabled: boolean;
  /**
   * Route-level header mapping, overriding the provider-level one for the same name. An empty string value deletes that header, and values support an ${api_key} placeholder.
   * @nullable
   */
  headers?: GatewayRouteHeaders;
  /**
   * What is known per endpoint — the route's only capability record.
   * One entry per probeable endpoint of each protocol the provider
   * speaks. A route declares nothing about what it serves: the data
   * plane tries any endpoint not found `unsupported`, and the
   * catalogue publishes any endpoint found `ok`.
   */
  probes?: GatewayRouteProbe[];
  /**
   * This upstream's context window override for the model; empty means use the model's own value. A relay often narrows it by its own policy.
   * @nullable
   */
  context_window?: number | null;
  /**
   * This upstream's output limit override; empty means use the model's own value
   * @nullable
   */
  max_output_tokens?: number | null;
  /**
   * The most images one request to this route can come back with. Empty means one.
   *
   * It is the image plane''s whole envelope, and what a per-image reservation is taken against: how many images a request produces is not knowable until it has been made, so the charge follows the response and the reservation has to cover the most it could have returned. Left at one, an organisation passes a budget check on the strength of one image and is then charged for however many the upstream chose to return.
   * @nullable
   */
  max_images?: number | null;
  /**
   * Upstream behaviour flags. Only `ignores_max_output_tokens` (a boolean) is recognised.
   * Setting it true means this upstream does not honour the output limit in the request — one relay was measured returning 94 tokens for a request capped at 16.
   * The pre-authorisation estimate then stops treating the request cap as an upper bound on cost; otherwise the credit guard stops working.
   */
  quirks?: GatewayRouteQuirks;
  video_envelope?: VideoEnvelope;
}

/**
 * A catalog entry created along the way.
 *
 * It is always disabled and carries no prices at all. The readiness gate remains the only way a model becomes enabled;
 * this exists solely so that a row upstream reports but the catalog lacks has something to attach to. The provider page marks
 * such rows as missing pricing straight away and links through to it — being attached is true, being sellable is not.
 *
 * A slug colliding with an existing one is reported as `failed` rather than reusing the model of that name: the same name is not
 * necessarily the same model — two relays can call different things `gpt-4o` — and silently reusing it attaches the route to the
 * wrong catalog entry. A caller renames and retries, or
 * switches to `model_id` to say explicitly which model to attach to.
 */
export interface GatewayRouteBatchNewModel {
  /** The model's identity here. Written `<creator>/<name>`, lowercase, where the creator is who made the model rather than which provider serves it. It cannot be changed once created, so the interface has to let someone check it first, and a bare upstream name is refused rather than stored. */
  slug: string;
  display_name?: string;
  /** Omitted or zero leaves it unset, the same as creating the model from the catalog page. It is here so a model created while wiring a provider can be as complete as one created directly — otherwise every discovered model arrives with a zero window and has to be finished one at a time on its own page. */
  context_window?: number;
  /** Omitted takes the same conservative default the catalog page applies, because an output cap of zero degrades the pre-authorisation estimate for requests that carry no max_tokens into an input-only one. */
  max_output_tokens?: number;
  output_modalities?: OutputModalities;
}

/**
 * Create one route. `provider_id` is not here because it is a path parameter:
 * a batch acts on exactly one provider, which is the scope of whole-set editing.
 *
 * Give exactly one of `model_id` and `new_model`. Use the former to attach an existing catalog entry;
 * use the latter when upstream reported a name the local catalog does not have — the unknown state from discovery —
 * which creates the catalog entry on the spot and attaches to it. Giving both, or neither, is rejected.
 *
 * Attributes take their defaults, and are changed by editing the row afterwards:
 * whole-set editing governs membership, not attributes.
 */
export interface GatewayRouteBatchCreate {
  model_id?: string;
  new_model?: GatewayRouteBatchNewModel;
  /** The model name this upstream recognises, written verbatim */
  provider_model_id: string;
}

/**
 * Delete one route. `model_id` is included because deletion matches on the route and model together,
 * the same way the model-scoped delete endpoint does.
 * A mismatched pair matches zero rows and is reported as `already`, so a caller cannot tell "exists but is not yours" apart from "does not exist".
 */
export interface GatewayRouteBatchDelete {
  model_id: string;
  route_id: string;
}

/**
 * What one whole-set save has to do. Both arrays are required, though either may be empty.
 * "Nothing to delete this time" and "deletion is not being handled this time" are different statements,
 * and an omitted field reads as the second. A caller can always compute both.
 */
export interface GatewayRouteBatchInput {
  creates: GatewayRouteBatchCreate[];
  deletes: GatewayRouteBatchDelete[];
}

export type GatewayRouteBatchItemResultKind =
  (typeof GatewayRouteBatchItemResultKind)[keyof typeof GatewayRouteBatchItemResultKind];

export const GatewayRouteBatchItemResultKind = {
  create: "create",
  delete: "delete",
} as const;

/**
 * `done` means it was carried out; `already` means the database was in the target state to begin with, from a creation hitting a unique constraint or a deletion finding nothing;
 * `failed` means it was not carried out, with the reason in the code and detail fields.
 * `already` counts as success, but a caller should report those separately, because they mean the list in hand is stale.
 */
export type GatewayRouteBatchItemResultOutcome =
  (typeof GatewayRouteBatchItemResultOutcome)[keyof typeof GatewayRouteBatchItemResultOutcome];

export const GatewayRouteBatchItemResultOutcome = {
  done: "done",
  already: "already",
  failed: "failed",
} as const;

/**
 * The outcome of one row.
 *
 * The model and upstream-model pair is there to be read by people: with the provider fixed,
 * those two dimensions are exactly what the database's unique key reduces to, so that pair is the row's identity
 * in logs and while troubleshooting.
 * To match results back to the request, however, use the index — see the note on `results`.
 */
export interface GatewayRouteBatchItemResult {
  kind: GatewayRouteBatchItemResultKind;
  /**
   * `done` means it was carried out; `already` means the database was in the target state to begin with, from a creation hitting a unique constraint or a deletion finding nothing;
   * `failed` means it was not carried out, with the reason in the code and detail fields.
   * `already` counts as success, but a caller should report those separately, because they mean the list in hand is stale.
   */
  outcome: GatewayRouteBatchItemResultOutcome;
  /**
   * Which model this row landed on. When `new_model` succeeded it is the id of the model just created;
   * when the model creation itself failed it is empty, because there is no model yet.
   * @nullable
   */
  model_id: string | null;
  /** On deletion the server fills this in from the row it deleted, so a caller need not know it beforehand */
  provider_model_id: string;
  /**
   * On a successful creation, the id of the new route; on deletion, the id of the one removed. Empty when the row failed.
   * @nullable
   */
  route_id?: string | null;
  /** The error code when the row failed, for example common.validation. Empty for any other outcome. */
  code?: string;
  /** The reason the row failed, in the same form as a problem response's detail. Empty for any other outcome. */
  detail?: string;
}

export interface GatewayRouteBatchResult {
  /**
   * One entry per request row, in the same order and of the same length as the creations followed by the deletions. A caller matches results back to its own
   * table by index — the only correspondence that holds in every case, because a row using `new_model` has no
   * model id beforehand and may still have none afterwards if the model creation failed.
   */
  results: GatewayRouteBatchItemResult[];
}

/**
 * @nullable
 */
export type GatewayRouteInputHeaders = { [key: string]: string } | null;

/**
 * Upstream behaviour flags. Only `ignores_max_output_tokens` (a boolean) is recognised.
 * Setting it true means this upstream does not honour the output limit in the request — one relay was measured returning 94 tokens for a request capped at 16.
 * The pre-authorisation estimate then stops treating the request cap as an upper bound on cost; otherwise the credit guard stops working.
 */
export type GatewayRouteInputQuirks = { [key: string]: unknown };

export interface GatewayRouteInput {
  provider_id?: string;
  provider_model_id?: string;
  priority?: number;
  weight?: number;
  enabled?: boolean;
  /** @nullable */
  headers?: GatewayRouteInputHeaders;
  /**
   * This upstream's context window override for the model; empty means use the model's own value. A relay often narrows it by its own policy.
   * @nullable
   */
  context_window?: number | null;
  /**
   * This upstream's output limit override; empty means use the model's own value
   * @nullable
   */
  max_output_tokens?: number | null;
  /**
   * The most images one request to this route can come back with. Empty means one.
   *
   * It is the image plane''s whole envelope, and what a per-image reservation is taken against: how many images a request produces is not knowable until it has been made, so the charge follows the response and the reservation has to cover the most it could have returned. Left at one, an organisation passes a budget check on the strength of one image and is then charged for however many the upstream chose to return.
   * @nullable
   */
  max_images?: number | null;
  /**
   * Upstream behaviour flags. Only `ignores_max_output_tokens` (a boolean) is recognised.
   * Setting it true means this upstream does not honour the output limit in the request — one relay was measured returning 94 tokens for a request capped at 16.
   * The pre-authorisation estimate then stops treating the request cap as an upper bound on cost; otherwise the credit guard stops working.
   */
  quirks?: GatewayRouteInputQuirks;
  /**
   * Supplied, it replaces the whole envelope; omitted, the existing one is kept. `source` inside it is ignored — the write path always records `declared`.
   *
   * **An empty object unconfigures the route**, which is how a route stops serving video. There is no null variant: the column is NOT NULL, so "no envelope" and "an envelope that declares nothing" are one stored state, and a second spelling of it would be one that quietly did nothing.
   */
  video_envelope?: VideoEnvelope;
}

