export type TestGatewayProviderBody = {
  /** The real upstream model name to probe with */
  upstream_model: string;
  /**
   * Which key to probe with. Omitting it keeps the earlier behaviour of taking the
   * first usable key in id order, which is the oldest one, so existing callers are unaffected.
   *
   * Without this parameter a standby key can never be verified: during a rotation one adds a
   * new key, runs the test, and still tests the old one, leaving the new key's verification
   * timestamp permanently unset — and that is precisely the key expected to take over when
   * the primary trips.
   *
   * It must belong to this provider, or the request is rejected with 400; otherwise another
   * provider's key id could be used to send that key to this provider's base URL.
   */
  key_id?: string;
  /**
   * Which endpoint to probe. The default is the canonical endpoint for the
   * provider's protocol. It must match that protocol, or the request is rejected with 400.
   * Note that one image probe costs considerably more than a text one.
   */
  endpoint?: TestGatewayProviderBodyEndpoint;
  /**
   * Return the full exchange: the address, and the request and response headers and
   * bodies. Available only outside production; a production deployment always ignores this
   * parameter and never emits the trace.
   *
   * The exchange is not redacted. The `Authorization` and `x-api-key` request headers, along
   * with any custom header the mapping substituted the API key into, contain the decrypted
   * key in the clear. That is exactly what makes it useful — "is the key I stored the same
   * one that actually goes out" can only be answered by seeing it — and exactly why
   * non-production is its boundary.
   */
  include_trace?: boolean;
};

